/**
 * Lightweight Zero-Dependency Panzoom for CCTV Canvas/Video
 */
window.createPanzoom = function(viewportEl, targetEl, options = {}) {
    let scale = 1;
    let minScale = options.minScale || 1;
    let maxScale = options.maxScale || 6;
    let pointX = 0;
    let pointY = 0;
    let startX = 0;
    let startY = 0;
    let isPanning = false;

    function updateTransform() {
        targetEl.style.transform = `translate(${pointX}px, ${pointY}px) scale(${scale})`;
    }

    function zoom(deltaScale, clientX, clientY) {
        const prevScale = scale;
        const rect = viewportEl.getBoundingClientRect();
        const offsetX = clientX !== undefined ? clientX - rect.left : rect.width / 2;
        const offsetY = clientY !== undefined ? clientY - rect.top : rect.height / 2;

        scale = Math.min(Math.max(scale * deltaScale, minScale), maxScale);

        if (scale === 1) {
            pointX = 0;
            pointY = 0;
        } else {
            pointX = offsetX - (offsetX - pointX) * (scale / prevScale);
            pointY = offsetY - (offsetY - pointY) * (scale / prevScale);
        }
        updateTransform();
    }

    viewportEl.addEventListener('wheel', (e) => {
        e.preventDefault();
        const factor = e.deltaY < 0 ? 1.2 : 0.83;
        zoom(factor, e.clientX, e.clientY);
    }, { passive: false });

    viewportEl.addEventListener('mousedown', (e) => {
        if (e.button !== 0 || scale <= 1) return;
        isPanning = true;
        startX = e.clientX - pointX;
        startY = e.clientY - pointY;
        viewportEl.style.cursor = 'grabbing';
    });

    window.addEventListener('mousemove', (e) => {
        if (!isPanning) return;
        pointX = e.clientX - startX;
        pointY = e.clientY - startY;
        updateTransform();
    });

    window.addEventListener('mouseup', () => {
        if (isPanning) {
            isPanning = false;
            viewportEl.style.cursor = scale > 1 ? 'grab' : 'default';
        }
    });

    viewportEl.addEventListener('dblclick', (e) => {
        e.preventDefault();
        if (scale > 1) {
            reset();
        } else {
            zoom(2, e.clientX, e.clientY);
        }
    });

    function reset() {
        scale = 1;
        pointX = 0;
        pointY = 0;
        updateTransform();
        viewportEl.style.cursor = 'default';
    }

    return {
        zoomIn: () => zoom(1.3),
        zoomOut: () => zoom(0.77),
        reset: reset,
        getScale: () => scale
    };
};

